<?php

# @autogenerated
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TrustedClient\Domain\ValueObject\Accessor\TrustedClientSecretOauthAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TrustedClientSecretOauthAccessor trait.
 *
 * Covers null default, string/VO assignment via withSecretOauth,
 * getSecretOauth/secretOauth accessors, and isSecretOauthChanged with/without original.
 */
class TrustedClientSecretOauthAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withSecretOauth creates a new instance with the SecretOauth set
     * from a string value, and getSecretOauth returns the primitive string.
     */
    public function testWithSecretOauthFromString(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientSecretOauthAccessorUnitTest();

        // Act
        $result = $holder->withSecretOauth('cyphered://cypher');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('****er', $result->getSecretOauth());
    }
    /**
     * Asserts that withsecretOauth has access to the value object
     * from a string value, and getSecretOauth returns the primitive string.
     */
    public function testWithSecretOauthFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientSecretOauthAccessorUnitTest();

        // Act
        $result = $holder->withSecretOauth('cyphered://cypher');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('****er', $result->secretOauth()->value());
    }
    public function testChangedSecretOauth(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientSecretOauthAccessorUnitTest();
        $original = $holder->withSecretOauth( 'cyphered://cypher');
        $same = $holder->withSecretOauth( 'cyphered://cypher');
        $modified = $holder->withSecretOauth('cyphered://ocyphered');

        // Act
        $unchanged = $holder->isSecretOauthChanged();
        $withSame = $original->isSecretOauthChanged( $same );
        $withDiferent = $original->isSecretOauthChanged( $modified );

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithTrustedClientSecretOauthAccessorUnitTest
{
  use TrustedClientSecretOauthAccessor;
}
